solution.code:
:root {
  --space: 16px;
  --space-sm: calc(var(--space) / 2);
  --space-lg: calc(var(--space) * 2);
  --bg: #ffffff;
  --text: #0f172a;
}
.theme-dark {
  --bg: #0f172a;
  --text: #f8fafc;
}
.panel {
  background: var(--bg);
  color: var(--text);
  padding: var(--space-lg);
  gap: var(--space-sm);
}
